// Git object core: content-addressed store, commits, trees, tree writes, ancestry.
import { sha1, type ObjType } from './packfile.ts'

export interface ObjRec {
  type: ObjType
  data: Buffer
}

export class ObjectStore {
  map = new Map<string, ObjRec>()
  treeMemo = new Map<string, { blobs: Map<string, { mode: string; sha: string }>; trees: Set<string> }>()

  store(type: ObjType, data: Buffer): string {
    const sha = sha1(type, data)
    if (!this.map.has(sha)) this.map.set(sha, { type, data })
    return sha
  }

  get(sha: string): ObjRec | undefined {
    return this.map.get(sha)
  }

  has(sha: string): boolean {
    return this.map.has(sha)
  }
}

export const EMPTY_TREE = '4b825dc642cb6eb9a060e54bf8d69288fbee4904'

export interface CommitRec {
  tree: string
  parents: string[]
  author: string
  committer: string
  message: string
}

export function parseCommit(data: Buffer): CommitRec {
  const text = data.toString('utf8')
  const idx = text.indexOf('\n\n')
  const head = idx === -1 ? text : text.slice(0, idx)
  const message = idx === -1 ? '' : text.slice(idx + 2)
  let tree = ''
  const parents: string[] = []
  let author = ''
  let committer = ''
  for (const line of head.split('\n')) {
    if (line.startsWith('tree ')) tree = line.slice(5).trim()
    else if (line.startsWith('parent ')) parents.push(line.slice(7).trim())
    else if (line.startsWith('author ')) author = line.slice(7)
    else if (line.startsWith('committer ')) committer = line.slice(10)
  }
  return { tree, parents, author, committer, message }
}

export interface TreeEntry {
  mode: string
  name: string
  sha: string
}

export function isDirMode(mode: string): boolean {
  return mode === '40000' || mode === '040000'
}

export function parseTree(data: Buffer): TreeEntry[] {
  const out: TreeEntry[] = []
  let p = 0
  while (p < data.length) {
    const sp = data.indexOf(32, p)
    const nul = data.indexOf(0, sp)
    if (sp === -1 || nul === -1 || nul + 21 > data.length) break
    const mode = data.toString('latin1', p, sp)
    const name = data.toString('utf8', sp + 1, nul)
    const sha = data.toString('hex', nul + 1, nul + 21)
    out.push({ mode, name, sha })
    p = nul + 21
  }
  return out
}

export function serializeTree(entries: TreeEntry[]): Buffer {
  const sorted = [...entries].sort((a, b) => {
    const an = a.name + (isDirMode(a.mode) ? '/' : '')
    const bn = b.name + (isDirMode(b.mode) ? '/' : '')
    return an < bn ? -1 : an > bn ? 1 : 0
  })
  const parts: Buffer[] = []
  for (const e of sorted) {
    parts.push(Buffer.from(`${e.mode} ${e.name}\0`, 'utf8'))
    parts.push(Buffer.from(e.sha, 'hex'))
  }
  return Buffer.concat(parts)
}

export function makeCommit(
  objects: ObjectStore,
  opts: { tree: string; parents: string[]; message: string; tsSec: number; who?: string },
): string {
  const ident = `${opts.who ?? 'Forge <<email>>'} ${opts.tsSec} +0000`
  const lines = [`tree ${opts.tree}`]
  for (const p of opts.parents) lines.push(`parent ${p}`)
  lines.push(`author ${ident}`, `committer ${ident}`, '', opts.message, '')
  return objects.store('commit', Buffer.from(lines.join('\n'), 'utf8'))
}

/** Full recursive closure of a tree: blob paths + all tree shas (memoized). */
export function treeClosure(objects: ObjectStore, treeSha: string): {
  blobs: Map<string, { mode: string; sha: string }>
  trees: Set<string>
} {
  const memo = objects.treeMemo
  const hit = memo.get(treeSha)
  if (hit) return hit
  const blobs = new Map<string, { mode: string; sha: string }>()
  const trees = new Set<string>([treeSha])
  const walk = (sha: string, prefix: string): void => {
    const rec = objects.get(sha)
    if (!rec) return
    for (const e of parseTree(rec.data)) {
      if (isDirMode(e.mode)) {
        trees.add(e.sha)
        walk(e.sha, prefix + e.name + '/')
      } else {
        blobs.set(prefix + e.name, { mode: e.mode, sha: e.sha })
      }
    }
  }
  walk(treeSha, '')
  const rec = { blobs, trees }
  memo.set(treeSha, rec)
  return rec
}

/**
 * Update a nested tree along a path. entry=null deletes. Returns the new tree
 * sha of this level, or null when this level becomes empty (callers drop it).
 */
export function updateTreePath(
  objects: ObjectStore,
  treeSha: string | null,
  segs: string[],
  entry: { mode: string; sha: string } | null,
): string | null {
  const rec = treeSha ? objects.get(treeSha) : undefined
  const entries = rec ? parseTree(rec.data) : []
  const name = segs[0]
  if (segs.length === 1) {
    const rest = entries.filter((e) => e.name !== name)
    if (entry) rest.push({ mode: entry.mode, name, sha: entry.sha })
    return objects.store('tree', serializeTree(rest))
  }
  const cur = entries.find((e) => e.name === name && isDirMode(e.mode))
  const newSub = updateTreePath(objects, cur ? cur.sha : null, segs.slice(1), entry)
  const rest = entries.filter((e) => e.name !== name)
  if (newSub !== null) rest.push({ mode: '40000', name, sha: newSub })
  return objects.store('tree', serializeTree(rest))
}

/** Walk a tree path to a blob entry. */
export function lookupPath(objects: ObjectStore, treeSha: string | null, segs: string[]): { mode: string; sha: string } | null {
  let cur: TreeEntry | null = treeSha ? { mode: '40000', name: '', sha: treeSha } : null
  for (let i = 0; i < segs.length; i++) {
    if (!cur) return null
    const rec = objects.get(cur.sha)
    if (!rec) return null
    const entries = parseTree(rec.data)
    const hit = entries.find((e) => e.name === segs[i]) ?? null
    if (!hit) return null
    if (i === segs.length - 1) return { mode: hit.mode, sha: hit.sha }
    if (!isDirMode(hit.mode)) return null
    cur = hit
  }
  return cur ? { mode: cur.mode, sha: cur.sha } : null
}

/** All ancestor commit shas of `sha` (inclusive), BFS with cap. */
export function ancestors(objects: ObjectStore, sha: string, cap = 20000): Set<string> {
  const seen = new Set<string>()
  const queue = [sha]
  seen.add(sha)
  while (queue.length && seen.size < cap) {
    const c = queue.shift()!
    const rec = objects.get(c)
    if (!rec) continue
    const commit = parseCommit(rec.data)
    for (const p of commit.parents) {
      if (!seen.has(p)) {
        seen.add(p)
        queue.push(p)
      }
    }
  }
  return seen
}

export function isAncestor(objects: ObjectStore, oldSha: string, newSha: string): boolean {
  if (oldSha === newSha) return true
  const seen = new Set<string>([newSha])
  const queue = [newSha]
  while (queue.length) {
    const c = queue.shift()!
    if (c === oldSha) return true
    const rec = objects.get(c)
    if (!rec) continue
    for (const p of parseCommit(rec.data).parents) {
      if (!seen.has(p)) {
        seen.add(p)
        queue.push(p)
      }
    }
  }
  return false
}

export function mergeBase(objects: ObjectStore, a: string, b: string): string | null {
  const ancA = ancestors(objects, a)
  const seen = new Set<string>([b])
  const queue = [b]
  while (queue.length) {
    const c = queue.shift()!
    if (ancA.has(c)) return c
    const rec = objects.get(c)
    if (!rec) continue
    for (const p of parseCommit(rec.data).parents) {
      if (!seen.has(p)) {
        seen.add(p)
        queue.push(p)
      }
    }
  }
  return null
}

// Packfile codec: parse incoming packs (full + delta objects), write packs for clone/fetch.
import zlib from 'node:zlib'
import crypto from 'node:crypto'

export const OBJ_COMMIT = 1
export const OBJ_TREE = 2
export const OBJ_BLOB = 3
export const OBJ_TAG = 4
export const OBJ_OFS_DELTA = 6
export const OBJ_REF_DELTA = 7

export type ObjType = 'commit' | 'tree' | 'blob' | 'tag'

export const TYPE_NUM: Record<ObjType, number> = { commit: 1, tree: 2, blob: 3, tag: 4 }
const NUM_TYPE: Record<number, ObjType> = { 1: 'commit', 2: 'tree', 3: 'blob', 4: 'tag' }

export function sha1(type: string, data: Buffer): string {
  const h = crypto.createHash('sha1')
  h.update(`${type} ${data.length}\0`, 'latin1')
  h.update(data)
  return h.digest('hex')
}

/**
 * Inflate a zlib stream starting at buf[pos]. inflateSync tolerates trailing
 * bytes, so the exact compressed length is found by binary search on the
 * prefix that inflates cleanly to exactly expectedSize bytes.
 */
export function inflateAt(buf: Buffer, pos: number, expectedSize: number): { data: Buffer; end: number } {
  let lo = pos + 2
  let hi = buf.length
  let bestEnd = -1
  let bestData: Buffer | null = null
  while (lo <= hi) {
    const mid = (lo + hi) >> 1
    let ok = false
    let out: Buffer | null = null
    try {
      out = zlib.inflateSync(buf.subarray(pos, mid))
      ok = out.length === expectedSize
    } catch {
      ok = false
    }
    if (ok && out) {
      bestEnd = mid
      bestData = out
      hi = mid - 1
    } else {
      lo = mid + 1
    }
  }
  if (bestEnd === -1 || !bestData) throw new Error(`inflate failed at ${pos} (want ${expectedSize})`)
  return { data: bestData, end: bestEnd }
}

export interface PackSink {
  get(sha: string): { type: ObjType; data: Buffer } | undefined
  store(type: ObjType, data: Buffer): string
}

/** Parse a pack v2/v3 buffer, applying ofs/ref deltas, storing every object into sink. */
export function unpackPack(buf: Buffer, sink: PackSink): number {
  if (buf.length < 32 || buf.toString('latin1', 0, 4) !== 'PACK') throw new Error('bad pack signature')
  const ver = buf.readUInt32BE(4)
  if (ver !== 2 && ver !== 3) throw new Error(`bad pack version ${ver}`)
  const count = buf.readUInt32BE(8)
  let pos = 12
  const offsetSha = new Map<number, string>()
  for (let i = 0; i < count; i++) {
    const objStart = pos
    let b = buf[pos++]
    const type = (b >> 4) & 7
    let size = b & 0x0f
    let shift = 4
    while (b & 0x80) {
      b = buf[pos++]
      size |= (b & 0x7f) << shift
      shift += 7
    }
    if (type === OBJ_OFS_DELTA) {
      let c = buf[pos++]
      let off = c & 0x7f
      while (c & 0x80) {
        c = buf[pos++]
        off = ((off + 1) << 7) | (c & 0x7f)
      }
      const r = inflateAt(buf, pos, size)
      pos = r.end
      const baseSha = offsetSha.get(objStart - off)
      if (!baseSha) throw new Error('bad ofs-delta base offset')
      const base = sink.get(baseSha)
      if (!base) throw new Error('ofs-delta base missing')
      offsetSha.set(objStart, sink.store(base.type, applyDelta(base.data, r.data)))
    } else if (type === OBJ_REF_DELTA) {
      const baseSha = buf.toString('hex', pos, pos + 20)
      pos += 20
      const r = inflateAt(buf, pos, size)
      pos = r.end
      const base = sink.get(baseSha)
      if (!base) throw new Error(`ref-delta base missing ${baseSha}`)
      offsetSha.set(objStart, sink.store(base.type, applyDelta(base.data, r.data)))
    } else {
      const t = NUM_TYPE[type]
      if (!t) throw new Error(`bad object type ${type}`)
      const r = inflateAt(buf, pos, size)
      pos = r.end
      offsetSha.set(objStart, sink.store(t, r.data))
    }
  }
  return count
}

export function applyDelta(base: Buffer, delta: Buffer): Buffer {
  let p = 0
  const sizeVarint = (): number => {
    let r = 0
    let s = 0
    for (;;) {
      const b = delta[p++]
      r |= (b & 0x7f) << s
      if (!(b & 0x80)) break
      s += 7
    }
    return r
  }
  const srcSize = sizeVarint()
  const tgtSize = sizeVarint()
  if (srcSize !== base.length) throw new Error('delta base size mismatch')
  const out = Buffer.alloc(tgtSize)
  let o = 0
  while (p < delta.length) {
    const c = delta[p++]
    if (c & 0x80) {
      let off = 0
      let len = 0
      if (c & 0x01) off |= delta[p++]
      if (c & 0x02) off |= delta[p++] << 8
      if (c & 0x04) off |= delta[p++] << 16
      if (c & 0x08) off |= delta[p++] << 24
      if (c & 0x10) len |= delta[p++]
      if (c & 0x20) len |= delta[p++] << 8
      if (c & 0x40) len |= delta[p++] << 16
      if (len === 0) len = 0x10000
      base.copy(out, o, off, off + len)
      o += len
    } else if (c > 0) {
      delta.copy(out, o, p, p + c)
      p += c
      o += c
    } else {
      throw new Error('bad delta opcode 0')
    }
  }
  if (o !== tgtSize) throw new Error('delta target size mismatch')
  return out
}

/** Write a pack (full objects, no deltas) with trailing checksum. */
export function packObjects(objs: { type: ObjType; data: Buffer }[]): Buffer {
  const parts: Buffer[] = []
  const head = Buffer.alloc(12)
  head.write('PACK', 0, 'latin1')
  head.writeUInt32BE(2, 4)
  head.writeUInt32BE(objs.length, 8)
  parts.push(head)
  for (const o of objs) {
    let first = (TYPE_NUM[o.type] << 4) | (o.data.length & 0x0f)
    let size = o.data.length >> 4
    const hb: number[] = []
    while (size > 0) {
      hb.push(first | 0x80)
      first = size & 0x7f
      size >>= 7
    }
    hb.push(first)
    parts.push(Buffer.from(hb))
    parts.push(zlib.deflateSync(o.data, { level: 1 }))
  }
  const body = Buffer.concat(parts)
  const sum = crypto.createHash('sha1').update(body).digest()
  return Buffer.concat([body, sum])
}

// ---- pkt-line helpers ----

export function pkt(s: string | Buffer): Buffer {
  const d = Buffer.isBuffer(s) ? s : Buffer.from(s, 'latin1')
  const hex = (d.length + 4).toString(16).padStart(4, '0')
  return Buffer.concat([Buffer.from(hex, 'latin1'), d])
}

export const FLUSH = Buffer.from('0000', 'latin1')
export const DELIM = Buffer.from('0001', 'latin1')

export interface PktLine {
  kind: 'data' | 'flush' | 'delim'
  data?: Buffer
}

export function readPkts(buf: Buffer): PktLine[] {
  const out: PktLine[] = []
  let p = 0
  while (p + 4 <= buf.length) {
    const hex = buf.toString('latin1', p, p + 4)
    const len = parseInt(hex, 16)
    if (Number.isNaN(len)) throw new Error('bad pkt-line length')
    if (len === 0) {
      out.push({ kind: 'flush' })
      p += 4
    } else if (len === 1) {
      out.push({ kind: 'delim' })
      p += 4
    } else if (len === 2) {
      out.push({ kind: 'flush' })
      p += 4
    } else {
      if (p + len > buf.length) throw new Error('truncated pkt-line')
      out.push({ kind: 'data', data: buf.subarray(p + 4, p + len) })
      p += len
    }
  }
  return out
}

export function sidebandChunk(band: number, data: Buffer, maxChunk = 65515): Buffer {
  const parts: Buffer[] = []
  for (let o = 0; o < data.length; o += maxChunk) {
    parts.push(pkt(Buffer.concat([Buffer.from([band]), data.subarray(o, o + maxChunk)])))
  }
  parts.push(FLUSH)
  return Buffer.concat(parts)
}

// Deterministic in-memory forge store: repos, refs, issues, PRs, labels, ids, clock.
import { ObjectStore, EMPTY_TREE, makeCommit, serializeTree, treeClosure, updateTreePath, parseTree, isDirMode, type TreeEntry } from './objects.ts'
import type { ObjType } from './packfile.ts'

// Logical clock: every mutating operation advances one tick, so two runs of the
// same suite produce identical ids and timestamps byte for byte.
const BASE_MS = 1767225600000 // 2026-01-01T00:00:00.000Z

export interface CommentRec {
  id: number
  body: string
  createdAt: Date
  updatedAt: Date
}

export interface IssueRec {
  dbId: number
  number: number
  title: string
  body: string
  state: 'open' | 'closed'
  labels: string[]
  createdAt: Date
  updatedAt: Date
  closedAt: Date | null
  comments: number
  commentsList: CommentRec[]
}

export interface PullRec {
  dbId: number
  number: number
  title: string
  body: string
  state: 'open' | 'closed'
  merged: boolean
  headRef: string
  baseRef: string
  headSha: string
  baseSha: string
  mergeCommitSha: string | null
  mergedAt: Date | null
  createdAt: Date
  updatedAt: Date
}

export interface LabelRec {
  dbId: number
  name: string
  color: string
}

export class Repo {
  owner: string
  name: string
  dbId: number
  description = ''
  defaultBranch = 'main'
  isPrivate = false
  createdAt: Date
  updatedAt: Date
  pushedAt: Date
  numSeq = 0
  issues = new Map<number, IssueRec>()
  pulls = new Map<number, PullRec>()
  labels = new Map<string, LabelRec>()
  refs = new Map<string, string>()
  packCache = new Map<string, Buffer>()

  constructor(owner: string, name: string, when: Date, dbId: number) {
    this.owner = owner
    this.name = name
    this.createdAt = when
    this.updatedAt = when
    this.pushedAt = when
    this.dbId = dbId
  }

  get fullName(): string {
    return `${this.owner}/${this.name}`
  }

  refSha(ref: string): string | null {
    if (ref.startsWith('refs/')) return this.refs.get(ref) ?? null
    return null
  }

  branchSha(branch: string): string | null {
    return this.refs.get(`refs/heads/${branch}`) ?? null
  }

  setRef(ref: string, sha: string): void {
    this.refs.set(ref, sha)
    this.packCache.clear()
  }

  deleteRef(ref: string): void {
    this.refs.delete(ref)
    this.packCache.clear()
  }
}

export class Store {
  objects = new ObjectStore()
  repos = new Map<string, Repo>()
  clock = BASE_MS
  reqCounter = 0
  repoId = 1000
  issueId = 2000
  pullId = 3000
  labelId = 4000
  commentId = 5000
  login = process.env.MAKEFUN_LOGIN || 'adaiversen'
  nodes = new Map<string, { kind: 'Repository' | 'Issue' | 'PullRequest'; repo: Repo; id: number }>()

  tick(): Date {
    this.clock += 1000
    return new Date(this.clock)
  }

  iso(): string {
    this.clock += 1000
    return new Date(this.clock).toISOString()
  }

  nextRequestId(): string {
    this.reqCounter += 1
    return `req-${this.reqCounter}`
  }

  nodeId(kind: string, dbId: number): string {
    return Buffer.from(`${kind}:${dbId}`, 'latin1').toString('base64')
  }

  getRepo(owner: string, name: string): Repo | null {
    return this.repos.get(`${owner}/${name}`) ?? null
  }

  createRepo(name: string, description = '', isPrivate = false, when = this.tick()): Repo {
    this.repoId += 1
    const repo = new Repo(this.login, name, when, this.repoId)
    repo.description = description
    repo.isPrivate = isPrivate
    this.repos.set(repo.fullName, repo)
    return repo
  }

  // ---- contents / commit helpers ----

  writeFile(repo: Repo, branch: string, path: string, data: Buffer | null, message: string, tsSec: number): { commit: string; blob: string | null } {
    const segs = path.split('/').filter((s) => s.length > 0)
    let blobSha: string | null = null
    if (data !== null) blobSha = this.objects.store('blob', data)
    const tip = repo.branchSha(branch)
    const baseTree = tip ? this.commitTree(tip) : null
    const entry = data === null ? null : { mode: '100644', sha: blobSha! }
    const newTree = updateTreePath(this.objects, baseTree, segs, entry) ?? EMPTY_TREE
    const commit = makeCommit(this.objects, {
      tree: newTree,
      parents: tip ? [tip] : [],
      message,
      tsSec,
    })
    repo.setRef(`refs/heads/${branch}`, commit)
    return { commit, blob: blobSha }
  }

  commitTree(commitSha: string): string {
    const rec = this.objects.get(commitSha)
    if (!rec) return EMPTY_TREE
    const m = rec.data.toString('utf8').match(/^tree ([0-9a-f]{40})/m)
    return m ? m[1] : EMPTY_TREE
  }

  fileAt(repo: Repo, branch: string, path: string): { mode: string; sha: string } | null {
    const tip = repo.branchSha(branch)
    if (!tip) return null
    const tree = this.commitTree(tip)
    const segs = path.split('/').filter((s) => s.length > 0)
    let cur: TreeEntry | null = { mode: '40000', name: '', sha: tree }
    for (let i = 0; i < segs.length; i++) {
      if (!cur) return null
      const rec = this.objects.get(cur.sha)
      if (!rec) return null
      const hit = parseTree(rec.data).find((e) => e.name === segs[i])
      if (!hit) return null
      if (i === segs.length - 1) return { mode: hit.mode, sha: hit.sha }
      if (!isDirMode(hit.mode)) return null
      cur = hit
    }
    return cur ? { mode: cur.mode, sha: cur.sha } : null
  }

  listDir(repo: Repo, branch: string, path: string): Array<{ mode: string; name: string; sha: string; kind: 'file' | 'dir' }> {
    const tip = repo.branchSha(branch)
    if (!tip) return []
    const tree = this.commitTree(tip)
    const segs = path.split('/').filter((s) => s.length > 0)
    let dirSha = tree
    for (const seg of segs) {
      const rec = this.objects.get(dirSha)
      if (!rec) return []
      const hit = parseTree(rec.data).find((e) => e.name === seg && isDirMode(e.mode))
      if (!hit) return []
      dirSha = hit.sha
    }
    const rec = this.objects.get(dirSha)
    if (!rec) return []
    return parseTree(rec.data).map((e) => ({
      mode: e.mode,
      name: e.name,
      sha: e.sha,
      kind: isDirMode(e.mode) ? 'dir' : 'file',
    }))
  }

  // ---- merge helpers ----

  /** Squash-merge `pull`: tree from head, single parent = base tip, onto base branch. */
  squashMerge(repo: Repo, pull: PullRec, message: string, tsSec: number): string {
    const headTip = repo.branchSha(pull.headRef)
    if (!headTip) throw new Error('head branch missing')
    const tree = this.commitTree(headTip)
    const baseTip = repo.branchSha(pull.baseRef) ?? ''
    const commit = makeCommit(this.objects, { tree, parents: [baseTip], message, tsSec })
    repo.setRef(`refs/heads/${pull.baseRef}`, commit)
    return commit
  }

  changedPathsBetween(aTree: string | null, bTree: string | null): Map<string, { a: { mode: string; sha: string } | null; b: { mode: string; sha: string } | null }> {
    const out = new Map<string, { a: { mode: string; sha: string } | null; b: { mode: string; sha: string } | null }>()
    const put = (path: string, side: 'a' | 'b', v: { mode: string; sha: string } | null): void => {
      const cur = out.get(path) ?? { a: null, b: null }
      cur[side] = v
      out.set(path, cur)
    }
    if (aTree) for (const [p, v] of treeClosure(this.objects, aTree).blobs) put(p, 'a', v)
    if (bTree) for (const [p, v] of treeClosure(this.objects, bTree).blobs) put(p, 'b', v)
    return out
  }

  /** 3-way conflict check for a pull request. Returns true when conflicted. */
  isConflicted(repo: Repo, pull: PullRec): boolean {
    const headTip = repo.branchSha(pull.headRef)
    const baseTip = repo.branchSha(pull.baseRef)
    if (!headTip || !baseTip) return false
    // common ancestor walk
    const ancBase = new Set<string>([baseTip])
    const q = [baseTip]
    while (q.length) {
      const c = q.shift()!
      const rec = this.objects.get(c)
      if (!rec) continue
      for (const line of rec.data.toString('utf8').split('\n')) {
        if (line.startsWith('parent ')) {
          const p = line.slice(7).trim()
          if (!ancBase.has(p)) {
            ancBase.add(p)
            q.push(p)
          }
        } else if (line === '') break
      }
    }
    let mb: string | null = null
    const seenH = new Set<string>([headTip])
    const qh = [headTip]
    while (qh.length) {
      const c = qh.shift()!
      if (ancBase.has(c)) {
        mb = c
        break
      }
      const rec = this.objects.get(c)
      if (!rec) continue
      for (const line of rec.data.toString('utf8').split('\n')) {
        if (line.startsWith('parent ')) {
          const p = line.slice(7).trim()
          if (!seenH.has(p)) {
            seenH.add(p)
            qh.push(p)
          }
        } else if (line === '') break
      }
    }
    const baseTree = this.commitTree(baseTip)
    const headTree = this.commitTree(headTip)
    const mbTree = mb ? this.commitTree(mb) : null
    const diff = this.changedPathsBetween(mbTree, baseTree)
    const headDiff = this.changedPathsBetween(mbTree, headTree)
    for (const [path, hb] of headDiff) {
      const bside = diff.get(path)
      if (!bside) continue
      const baseChanged = (bside.a?.sha ?? null) !== (bside.b?.sha ?? null)
      const headChanged = (hb.a?.sha ?? null) !== (hb.b?.sha ?? null)
      if (!baseChanged || !headChanged) continue
      const baseVer = bside.b?.sha ?? null
      const headVer = hb.b?.sha ?? null
      if (baseVer !== headVer) return true
    }
    return false
  }
}

export function storeObject(store: Store, type: ObjType, data: Buffer): string {
  return store.objects.store(type, data)
}

export function emptyTreeSha(store: Store): string {
  if (!store.objects.has(EMPTY_TREE)) store.objects.store('tree', serializeTree([]))
  return EMPTY_TREE
}

// HTTP plumbing: routing, auth, body collection, top-level error handling.
import http from 'node:http'
import zlib from 'node:zlib'
import { Store } from './store.ts'
import { handleRest } from './rest.ts'
import { handleGraphQL } from './graphql.ts'
import { handleMcp } from './mcp.ts'
import { handleGit } from './smarthttp.ts'

function collectBody(req: http.IncomingMessage, limit = 512 * 1024 * 1024): Promise<Buffer> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = []
    let size = 0
    req.on('data', (c: Buffer) => {
      size += c.length
      if (size > limit) {
        reject(new Error('body too large'))
        req.destroy()
        return
      }
      chunks.push(c)
    })
    req.on('end', () => resolve(Buffer.concat(chunks)))
    req.on('error', reject)
  })
}

export function createForgeServer(store: Store): http.Server {
  const server = http.createServer((req, res) => {
    void handleRequest(store, req, res)
  })
  server.on('checkContinue', (req, res) => {
    res.writeContinue()
    void handleRequest(store, req, res)
  })
  server.keepAliveTimeout = 65_000
  server.requestTimeout = 0
  server.headersTimeout = 60_000
  return server
}

async function handleRequest(store: Store, req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
  try {
    const url = new URL(req.url ?? '/', 'http://localhost')
    const pathname = url.pathname
    let raw: Buffer | null = null
    if (req.method !== 'GET' && req.method !== 'HEAD') {
      raw = await collectBody(req)
      const enc = String(req.headers['content-encoding'] ?? '').toLowerCase()
      if (enc.includes('gzip') && raw.length > 0) {
        try {
          raw = zlib.gunzipSync(raw)
        } catch {
          sendPlain(res, 400, { message: 'Problems parsing JSON' })
          return
        }
      }
    } else {
      raw = Buffer.alloc(0)
    }

    // Health probe (env boot check: 200 {"ok":true})
    if (pathname === '/healthz' && (req.method === 'GET' || req.method === 'HEAD')) {
      const body = Buffer.from(JSON.stringify({ ok: true }) + '\n', 'utf8')
      res.writeHead(200, {
        'Content-Type': 'application/json; charset=utf-8',
        'Content-Length': String(body.length),
      })
      res.end(body)
      return
    }

    // MCP endpoint (before git fallback)
    if (pathname === '/mcp') {
      const auth = String(req.headers.authorization ?? '')
      const bearer = auth.startsWith('Bearer ') ? auth.slice(7).trim() : null
      const token = process.env.MAKEFUN_SHOP_TOKEN
      const authed = bearer !== null && bearer.length > 0 && (token === undefined || token === '' || bearer === token)
      if (!authed) {
        sendPlain(res, 401, { message: 'Requires authentication' })
        return
      }
      if (req.method !== 'POST') {
        sendPlain(res, 405, { message: 'method not allowed' })
        return
      }
      const sessionId = typeof req.headers['mcp-session-id'] === 'string' ? (req.headers['mcp-session-id'] as string) : null
      handleMcp(store, raw.toString('utf8'), res, sessionId, (status, body, sid) => {
        const headers: Record<string, string> = { 'Content-Length': String(body.length) }
        if (body.length > 0) headers['Content-Type'] = 'application/json'
        if (sid) headers['Mcp-Session-Id'] = sid
        res.writeHead(status, headers)
        res.end(body)
      })
      return
    }

    // git smart HTTP: no auth required
    if (!pathname.startsWith('/api/')) {
      const isGit = pathname.endsWith('.git/info/refs') || pathname.endsWith('.git/git-upload-pack') || pathname.endsWith('.git/git-receive-pack') || pathname.includes('.git/')
      if (isGit || /^\/[^/]+\/[^/]+\.git(\/|$)/.test(pathname)) {
        const handled = handleGit(store, req.method ?? 'GET', pathname, url.searchParams, req.headers, raw, res)
        if (handled) return
      }
      sendPlain(res, 404, { message: 'Not Found' })
      return
    }

    // auth for API surfaces
    const auth = String(req.headers.authorization ?? '')
    const bearer = auth.startsWith('Bearer ') ? auth.slice(7).trim() : null
    const token = process.env.MAKEFUN_SHOP_TOKEN
    const authed = bearer !== null && bearer.length > 0 && (token === undefined || token === '' || bearer === token)
    if (!authed) {
      sendPlain(res, 401, { message: 'Requires authentication' })
      return
    }

