// Core Git object storage, tree graph serialization, commit synthesis, and ancestry traversal.
import { sha1, type ObjType } from './packfile.ts'

export interface ObjRec {
  type: ObjType
  data: Buffer
}

export class ObjectStore {
  readonly map = new Map<string, ObjRec>()
  readonly treeMemo = new Map<string, { blobs: Map<string, { mode: string; sha: string }>; trees: Set<string> }>()

  store(objType: ObjType, rawBytes: Buffer): string {
    const objectHash = sha1(objType, rawBytes)
    if (!this.map.has(objectHash)) {
      this.map.set(objectHash, { type: objType, data: rawBytes })
    }
    return objectHash
  }

  get(hash: string): ObjRec | undefined {
    return this.map.get(hash)
  }

  has(hash: string): boolean {
    return this.map.has(hash)
  }
}

export const EMPTY_TREE = '4b825dc642cb6eb9a060e54bf8d69288fbee4904'

export interface CommitRec {
  tree: string
  parents: string[]
  author: string
  committer: string
  message: string
}

export function parseCommit(commitBytes: Buffer): CommitRec {
  const fullText = commitBytes.toString('utf8')
  const splitPoint = fullText.indexOf('\n\n')
  const headerSection = splitPoint === -1 ? fullText : fullText.slice(0, splitPoint)
  const commitMsg = splitPoint === -1 ? '' : fullText.slice(splitPoint + 2)
  let treeOid = ''
  const parentOids: string[] = []
  let authorSig = ''
  let committerSig = ''
  for (const rawLine of headerSection.split('\n')) {
    if (rawLine.startsWith('tree ')) {
      treeOid = rawLine.slice(5).trim()
    } else if (rawLine.startsWith('parent ')) {
      parentOids.push(rawLine.slice(7).trim())
    } else if (rawLine.startsWith('author ')) {
      authorSig = rawLine.slice(7)
    } else if (rawLine.startsWith('committer ')) {
      committerSig = rawLine.slice(10)
    }
  }
  return {
    tree: treeOid,
    parents: parentOids,
    author: authorSig,
    committer: committerSig,
    message: commitMsg,
  }
}

export interface TreeEntry {
  mode: string
  name: string
  sha: string
}

export function isDirMode(entryMode: string): boolean {
  return entryMode === '40000' || entryMode === '040000'
}

export function parseTree(treeBuffer: Buffer): TreeEntry[] {
  const parsedEntries: TreeEntry[] = []
  let cursor = 0
  while (cursor < treeBuffer.length) {
    const spaceOffset = treeBuffer.indexOf(32, cursor)
    const nullOffset = treeBuffer.indexOf(0, spaceOffset)
    if (spaceOffset === -1 || nullOffset === -1 || nullOffset + 21 > treeBuffer.length) {
      break
    }
    const itemMode = treeBuffer.toString('latin1', cursor, spaceOffset)
    const itemName = treeBuffer.toString('utf8', spaceOffset + 1, nullOffset)
    const itemSha = treeBuffer.toString('hex', nullOffset + 1, nullOffset + 21)
    parsedEntries.push({ mode: itemMode, name: itemName, sha: itemSha })
    cursor = nullOffset + 21
  }
  return parsedEntries
}

export function serializeTree(treeItems: TreeEntry[]): Buffer {
  const ordered = [...treeItems].sort((left, right) => {
    const leftPath = left.name + (isDirMode(left.mode) ? '/' : '')
    const rightPath = right.name + (isDirMode(right.mode) ? '/' : '')
    return leftPath < rightPath ? -1 : leftPath > rightPath ? 1 : 0
  })
  const chunks: Buffer[] = []
  for (const item of ordered) {
    chunks.push(Buffer.from(`${item.mode} ${item.name}\0`, 'utf8'))
    chunks.push(Buffer.from(item.sha, 'hex'))
  }
  return Buffer.concat(chunks)
}

export function makeCommit(
  storage: ObjectStore,
  params: { tree: string; parents: string[]; message: string; tsSec: number; who?: string },
): string {
  const authorIdentity = `${params.who ?? 'Forge <<email>>'} ${params.tsSec} +0000`
  const commitLines = [`tree ${params.tree}`]
  for (const parentSha of params.parents) {
    commitLines.push(`parent ${parentSha}`)
  }
  commitLines.push(`author ${authorIdentity}`, `committer ${authorIdentity}`, '', params.message, '')
  return storage.store('commit', Buffer.from(commitLines.join('\n'), 'utf8'))
}

/** Full recursive closure of a tree: blob paths + all tree shas (memoized). */
export function treeClosure(storage: ObjectStore, rootTreeSha: string): {
  blobs: Map<string, { mode: string; sha: string }>
  trees: Set<string>
} {
  const cache = storage.treeMemo
  const existing = cache.get(rootTreeSha)
  if (existing) return existing
  const collectedBlobs = new Map<string, { mode: string; sha: string }>()
  const collectedTrees = new Set<string>([rootTreeSha])
  const traverse = (currentSha: string, currentPrefix: string): void => {
    const itemRecord = storage.get(currentSha)
    if (!itemRecord) return
    for (const treeElem of parseTree(itemRecord.data)) {
      if (isDirMode(treeElem.mode)) {
        collectedTrees.add(treeElem.sha)
        traverse(treeElem.sha, currentPrefix + treeElem.name + '/')
      } else {
        collectedBlobs.set(currentPrefix + treeElem.name, { mode: treeElem.mode, sha: treeElem.sha })
      }
    }
  }
  traverse(rootTreeSha, '')
  const closureResult = { blobs: collectedBlobs, trees: collectedTrees }
  cache.set(rootTreeSha, closureResult)
  return closureResult
}

/**
 * Update a nested tree along a path. entry=null deletes. Returns the new tree
 * sha of this level, or null when this level becomes empty (callers drop it).
 */
export function updateTreePath(
  storage: ObjectStore,
  currentTreeSha: string | null,
  pathSegments: string[],
  leafEntry: { mode: string; sha: string } | null,
): string | null {
  const record = currentTreeSha ? storage.get(currentTreeSha) : undefined
  const existingList = record ? parseTree(record.data) : []
  const headSegment = pathSegments[0]
  if (pathSegments.length === 1) {
    const filtered = existingList.filter((elem) => elem.name !== headSegment)
    if (leafEntry) {
      filtered.push({ mode: leafEntry.mode, name: headSegment, sha: leafEntry.sha })
    }
    return storage.store('tree', serializeTree(filtered))
  }
  const childSubtree = existingList.find((elem) => elem.name === headSegment && isDirMode(elem.mode))
  const updatedChildSha = updateTreePath(storage, childSubtree ? childSubtree.sha : null, pathSegments.slice(1), leafEntry)
  const remaining = existingList.filter((elem) => elem.name !== headSegment)
  if (updatedChildSha !== null) {
    remaining.push({ mode: '40000', name: headSegment, sha: updatedChildSha })
  }
  return storage.store('tree', serializeTree(remaining))
}

/** Walk a tree path to a blob entry. */
export function lookupPath(
  storage: ObjectStore,
  initialTreeSha: string | null,
  segments: string[],
): { mode: string; sha: string } | null {
  let activeEntry: TreeEntry | null = initialTreeSha ? { mode: '40000', name: '', sha: initialTreeSha } : null
  for (let idx = 0; idx < segments.length; idx++) {
    if (!activeEntry) return null
    const record = storage.get(activeEntry.sha)
    if (!record) return null
    const entries = parseTree(record.data)
    const match = entries.find((elem) => elem.name === segments[idx]) ?? null
    if (!match) return null
    if (idx === segments.length - 1) return { mode: match.mode, sha: match.sha }
    if (!isDirMode(match.mode)) return null
    activeEntry = match
  }
  return activeEntry ? { mode: activeEntry.mode, sha: activeEntry.sha } : null
}

/** All ancestor commit shas of `targetSha` (inclusive), BFS with cap. */
export function ancestors(storage: ObjectStore, targetSha: string, maxCap = 20000): Set<string> {
  const visitedSet = new Set<string>()
  const pendingQueue = [targetSha]
  visitedSet.add(targetSha)
  while (pendingQueue.length && visitedSet.size < maxCap) {
    const commitId = pendingQueue.shift()!
    const rec = storage.get(commitId)
    if (!rec) continue
    const parsed = parseCommit(rec.data)
    for (const pSha of parsed.parents) {
      if (!visitedSet.has(pSha)) {
        visitedSet.add(pSha)
        pendingQueue.push(pSha)
      }
    }
  }
  return visitedSet
}

export function isAncestor(storage: ObjectStore, ancestorCandidate: string, descendantSha: string): boolean {
  if (ancestorCandidate === descendantSha) return true
  const visited = new Set<string>([descendantSha])
  const searchQueue = [descendantSha]
  while (searchQueue.length) {
    const currentSha = searchQueue.shift()!
    if (currentSha === ancestorCandidate) return true
    const rec = storage.get(currentSha)
    if (!rec) continue
    for (const parentId of parseCommit(rec.data).parents) {
      if (!visited.has(parentId)) {
        visited.add(parentId)
        searchQueue.push(parentId)
      }
    }
  }
  return false
}

export function mergeBase(storage: ObjectStore, commitAlpha: string, commitBeta: string): string | null {
  const alphaAncestors = ancestors(storage, commitAlpha)
  const visitedBeta = new Set<string>([commitBeta])
  const betaQueue = [commitBeta]
  while (betaQueue.length) {
    const currentBetaSha = betaQueue.shift()!
    if (alphaAncestors.has(currentBetaSha)) return currentBetaSha
    const rec = storage.get(currentBetaSha)
    if (!rec) continue
    for (const p of parseCommit(rec.data).parents) {
      if (!visitedBeta.has(p)) {
        visitedBeta.add(p)
        betaQueue.push(p)
      }
    }
  }
  return null
}

// Packfile binary codec: delta unpacking, object inflation, pack assembly, and pkt-line transport framing.
import zlib from 'node:zlib'
import crypto from 'node:crypto'

export const OBJ_COMMIT = 1
export const OBJ_TREE = 2
export const OBJ_BLOB = 3
export const OBJ_TAG = 4
export const OBJ_OFS_DELTA = 6
export const OBJ_REF_DELTA = 7

export type ObjType = 'commit' | 'tree' | 'blob' | 'tag'

export const TYPE_NUM: Record<ObjType, number> = { commit: 1, tree: 2, blob: 3, tag: 4 }
const NUM_TO_TYPE: Record<number, ObjType> = { 1: 'commit', 2: 'tree', 3: 'blob', 4: 'tag' }

export function sha1(objectKind: string, payload: Buffer): string {
  const hasher = crypto.createHash('sha1')
  hasher.update(`${objectKind} ${payload.length}\0`, 'latin1')
  hasher.update(payload)
  return hasher.digest('hex')
}

/**
 * Inflate a zlib stream starting at inputBuffer[offset]. inflateSync tolerates trailing
 * bytes, so the exact compressed length is found by binary search on the
 * prefix that inflates cleanly to exactly targetSize bytes.
 */
export function inflateAt(
  inputBuffer: Buffer,
  startOffset: number,
  targetSize: number,
): { data: Buffer; end: number } {
  let lowerBound = startOffset + 2
  let upperBound = inputBuffer.length
  let finalEnd = -1
  let decompressedBytes: Buffer | null = null
  while (lowerBound <= upperBound) {
    const candidateEnd = (lowerBound + upperBound) >> 1
    let success = false
    let candidateOut: Buffer | null = null
    try {
      candidateOut = zlib.inflateSync(inputBuffer.subarray(startOffset, candidateEnd))
      success = candidateOut.length === targetSize
    } catch {
      success = false
    }
    if (success && candidateOut) {
      finalEnd = candidateEnd
      decompressedBytes = candidateOut
      upperBound = candidateEnd - 1
    } else {
      lowerBound = candidateEnd + 1
    }
  }
  if (finalEnd === -1 || !decompressedBytes) {
    throw new Error(`inflate failed at ${startOffset} (want ${targetSize})`)
  }
  return { data: decompressedBytes, end: finalEnd }
}

export interface PackSink {
  get(sha: string): { type: ObjType; data: Buffer } | undefined
  store(type: ObjType, data: Buffer): string
}

/** Parse a pack v2/v3 buffer, applying ofs/ref deltas, storing every object into sink. */
export function unpackPack(packRaw: Buffer, targetSink: PackSink): number {
  if (packRaw.length < 32 || packRaw.toString('latin1', 0, 4) !== 'PACK') {
    throw new Error('bad pack signature')
  }
  const packVersion = packRaw.readUInt32BE(4)
  if (packVersion !== 2 && packVersion !== 3) {
    throw new Error(`bad pack version ${packVersion}`)
  }
  const totalObjects = packRaw.readUInt32BE(8)
  let readPos = 12
  const offsetToShaMap = new Map<number, string>()
  for (let itemIdx = 0; itemIdx < totalObjects; itemIdx++) {
    const objectStartPos = readPos
    let byteVal = packRaw[readPos++]
    const rawType = (byteVal >> 4) & 7
    let uncompressedSize = byteVal & 0x0f
    let bitShift = 4
    while (byteVal & 0x80) {
      byteVal = packRaw[readPos++]
      uncompressedSize |= (byteVal & 0x7f) << bitShift
      bitShift += 7
    }
    if (rawType === OBJ_OFS_DELTA) {
      let deltaByte = packRaw[readPos++]
      let negativeOffset = deltaByte & 0x7f
      while (deltaByte & 0x80) {
        deltaByte = packRaw[readPos++]
        negativeOffset = ((negativeOffset + 1) << 7) | (deltaByte & 0x7f)
      }
      const inflation = inflateAt(packRaw, readPos, uncompressedSize)
      readPos = inflation.end
      const baseObjectSha = offsetToShaMap.get(objectStartPos - negativeOffset)
      if (!baseObjectSha) throw new Error('bad ofs-delta base offset')
      const baseRec = targetSink.get(baseObjectSha)
      if (!baseRec) throw new Error('ofs-delta base missing')
      const reconstructed = applyDelta(baseRec.data, inflation.data)
      offsetToShaMap.set(objectStartPos, targetSink.store(baseRec.type, reconstructed))
    } else if (rawType === OBJ_REF_DELTA) {
      const baseRefSha = packRaw.toString('hex', readPos, readPos + 20)
      readPos += 20
      const inflation = inflateAt(packRaw, readPos, uncompressedSize)
      readPos = inflation.end
      const baseRec = targetSink.get(baseRefSha)
      if (!baseRec) throw new Error(`ref-delta base missing ${baseRefSha}`)
      const reconstructed = applyDelta(baseRec.data, inflation.data)
      offsetToShaMap.set(objectStartPos, targetSink.store(baseRec.type, reconstructed))
    } else {
      const resolvedKind = NUM_TO_TYPE[rawType]
      if (!resolvedKind) throw new Error(`bad object type ${rawType}`)
      const inflation = inflateAt(packRaw, readPos, uncompressedSize)
      readPos = inflation.end
      offsetToShaMap.set(objectStartPos, targetSink.store(resolvedKind, inflation.data))
    }
  }
  return totalObjects
}

export function applyDelta(baseBuffer: Buffer, deltaInstructions: Buffer): Buffer {
  let deltaIdx = 0
  const readVarint = (): number => {
    let accumulated = 0
    let shiftAmount = 0
    for (;;) {
      const byte = deltaInstructions[deltaIdx++]
      accumulated |= (byte & 0x7f) << shiftAmount
      if (!(byte & 0x80)) break
      shiftAmount += 7
    }
    return accumulated
  }
  const sourceLen = readVarint()
  const targetLen = readVarint()
  if (sourceLen !== baseBuffer.length) {
    throw new Error('delta base size mismatch')
  }
  const resultBuffer = Buffer.alloc(targetLen)
  let outCursor = 0
  while (deltaIdx < deltaInstructions.length) {
    const opcode = deltaInstructions[deltaIdx++]
    if (opcode & 0x80) {
      let copyOffset = 0
      let copyLength = 0
      if (opcode & 0x01) copyOffset |= deltaInstructions[deltaIdx++]
      if (opcode & 0x02) copyOffset |= deltaInstructions[deltaIdx++] << 8
      if (opcode & 0x04) copyOffset |= deltaInstructions[deltaIdx++] << 16
      if (opcode & 0x08) copyOffset |= deltaInstructions[deltaIdx++] << 24
      if (opcode & 0x10) copyLength |= deltaInstructions[deltaIdx++]
      if (opcode & 0x20) copyLength |= deltaInstructions[deltaIdx++] << 8
      if (opcode & 0x40) copyLength |= deltaInstructions[deltaIdx++] << 16
      if (copyLength === 0) copyLength = 0x10000
      baseBuffer.copy(resultBuffer, outCursor, copyOffset, copyOffset + copyLength)
      outCursor += copyLength
    } else if (opcode > 0) {
      deltaInstructions.copy(resultBuffer, outCursor, deltaIdx, deltaIdx + opcode)
      deltaIdx += opcode
      outCursor += opcode
    } else {
      throw new Error('bad delta opcode 0')
    }
  }
  if (outCursor !== targetLen) {
    throw new Error('delta target size mismatch')
  }
  return resultBuffer
}

/** Write a pack (full objects, no deltas) with trailing checksum. */
export function packObjects(items: { type: ObjType; data: Buffer }[]): Buffer {
  const binaryParts: Buffer[] = []
  const packHeader = Buffer.alloc(12)
  packHeader.write('PACK', 0, 'latin1')
  packHeader.writeUInt32BE(2, 4)
  packHeader.writeUInt32BE(items.length, 8)
  binaryParts.push(packHeader)
  for (const obj of items) {
    let initialByte = (TYPE_NUM[obj.type] << 4) | (obj.data.length & 0x0f)
    let remainingSize = obj.data.length >> 4
    const headerBytes: number[] = []
    while (remainingSize > 0) {
      headerBytes.push(initialByte | 0x80)
      initialByte = remainingSize & 0x7f
      remainingSize >>= 7
    }
    headerBytes.push(initialByte)
    binaryParts.push(Buffer.from(headerBytes))
    binaryParts.push(zlib.deflateSync(obj.data, { level: 1 }))
  }
  const packContent = Buffer.concat(binaryParts)
  const checksum = crypto.createHash('sha1').update(packContent).digest()
  return Buffer.concat([packContent, checksum])
}

// ---- pkt-line helpers ----

export function pkt(linePayload: string | Buffer): Buffer {
  const bufData = Buffer.isBuffer(linePayload) ? linePayload : Buffer.from(linePayload, 'latin1')
  const hexLen = (bufData.length + 4).toString(16).padStart(4, '0')
  return Buffer.concat([Buffer.from(hexLen, 'latin1'), bufData])
}

export const FLUSH = Buffer.from('0000', 'latin1')
export const DELIM = Buffer.from('0001', 'latin1')

export interface PktLine {
  kind: 'data' | 'flush' | 'delim'
  data?: Buffer
}

export function readPkts(rawInput: Buffer): PktLine[] {
  const pktResults: PktLine[] = []
  let readPtr = 0
  while (readPtr + 4 <= rawInput.length) {
    const lenHex = rawInput.toString('latin1', readPtr, readPtr + 4)
    const lineLen = parseInt(lenHex, 16)
    if (Number.isNaN(lineLen)) throw new Error('bad pkt-line length')
    if (lineLen === 0) {
      pktResults.push({ kind: 'flush' })
      readPtr += 4
    } else if (lineLen === 1) {
      pktResults.push({ kind: 'delim' })
      readPtr += 4
    } else if (lineLen === 2) {
      pktResults.push({ kind: 'flush' })
      readPtr += 4
    } else {
      if (readPtr + lineLen > rawInput.length) throw new Error('truncated pkt-line')
      pktResults.push({ kind: 'data', data: rawInput.subarray(readPtr + 4, readPtr + lineLen) })
      readPtr += lineLen
    }
  }
  return pktResults
}

export function sidebandChunk(channelBand: number, payloadData: Buffer, chunkSize = 65515): Buffer {
  const streamChunks: Buffer[] = []
  for (let offset = 0; offset < payloadData.length; offset += chunkSize) {
    const slice = payloadData.subarray(offset, offset + chunkSize)
    streamChunks.push(pkt(Buffer.concat([Buffer.from([channelBand]), slice])))
  }
  streamChunks.push(FLUSH)
  return Buffer.concat(streamChunks)
}

// Deterministic in-memory database engine: state tree, repository metadata, refs, issues, PRs, and monotonic logical clock.
import {
  ObjectStore,
  EMPTY_TREE,
  makeCommit,
  serializeTree,
  treeClosure,
  updateTreePath,
  parseTree,
  isDirMode,
  type TreeEntry,
} from './objects.ts'
import type { ObjType } from './packfile.ts'

// Monotonic logical epoch base: 2026-01-01T00:00:00.000Z
const BASE_TIMESTAMP_MS = 1767225600000

export interface CommentRec {
  id: number
  body: string
  createdAt: Date
  updatedAt: Date
}

export interface IssueRec {
  dbId: number
  number: number
  title: string
  body: string
  state: 'open' | 'closed'
  labels: string[]
  createdAt: Date
  updatedAt: Date
  closedAt: Date | null
  comments: number
  commentsList: CommentRec[]
}

export interface PullRec {
  dbId: number
  number: number
  title: string
  body: string
  state: 'open' | 'closed'
  merged: boolean
  headRef: string
  baseRef: string
  headSha: string
  baseSha: string
  mergeCommitSha: string | null
  mergedAt: Date | null
  createdAt: Date
  updatedAt: Date
}

export interface LabelRec {
  dbId: number
  name: string
  color: string
}

export class Repo {
  readonly owner: string
  readonly name: string
  readonly dbId: number
  description = ''
  defaultBranch = 'main'
  isPrivate = false
  createdAt: Date
  updatedAt: Date
  pushedAt: Date
  numSeq = 0
  readonly issues = new Map<number, IssueRec>()
  readonly pulls = new Map<number, PullRec>()
  readonly labels = new Map<string, LabelRec>()
  readonly refs = new Map<string, string>()
  readonly packCache = new Map<string, Buffer>()

  constructor(repoOwner: string, repoName: string, initDate: Date, databaseId: number) {
    this.owner = repoOwner
    this.name = repoName
    this.createdAt = initDate
    this.updatedAt = initDate
    this.pushedAt = initDate
    this.dbId = databaseId
  }

  get fullName(): string {
    return `${this.owner}/${this.name}`
  }

  refSha(refName: string): string | null {
    if (refName.startsWith('refs/')) {
      return this.refs.get(refName) ?? null
    }
    return null
  }

  branchSha(branchIdentifier: string): string | null {
    return this.refs.get(`refs/heads/${branchIdentifier}`) ?? null
  }

  setRef(referenceName: string, commitOid: string): void {
    this.refs.set(referenceName, commitOid)
    this.packCache.clear()
  }

  deleteRef(referenceName: string): void {
    this.refs.delete(referenceName)
    this.packCache.clear()
  }
}

export class Store {
  readonly objects = new ObjectStore()
  readonly repos = new Map<string, Repo>()
  private logicalClock = BASE_TIMESTAMP_MS
  private requestSequence = 0
  private nextRepoDbId = 1000
  nextIssueDbId = 2000
  nextPullDbId = 3000
  nextLabelDbId = 4000
  nextCommentDbId = 5000
  readonly login = process.env.MAKEFUN_LOGIN || 'adaiversen'
  readonly nodes = new Map<string, { kind: 'Repository' | 'Issue' | 'PullRequest'; repo: Repo; id: number }>()

  tick(): Date {
    this.logicalClock += 1000
    return new Date(this.logicalClock)
  }

  iso(): string {
    this.logicalClock += 1000
    return new Date(this.logicalClock).toISOString()
  }

  nextRequestId(): string {
    this.requestSequence += 1
    return `req-${this.requestSequence}`
  }

  nodeId(typeName: string, entityId: number): string {
    return Buffer.from(`${typeName}:${entityId}`, 'latin1').toString('base64')
  }

  getRepo(userLogin: string, projectSlug: string): Repo | null {
    return this.repos.get(`${userLogin}/${projectSlug}`) ?? null
  }

  createRepo(
    repoSlug: string,
    descSummary = '',
    privateVisibility = false,
    creationTimestamp = this.tick(),
  ): Repo {
    this.nextRepoDbId += 1
    const newRepoInstance = new Repo(this.login, repoSlug, creationTimestamp, this.nextRepoDbId)
    newRepoInstance.description = descSummary
    newRepoInstance.isPrivate = privateVisibility
    this.repos.set(newRepoInstance.fullName, newRepoInstance)
    return newRepoInstance
  }

  // ---- contents / commit helpers ----

  writeFile(
    repository: Repo,
    targetBranch: string,
    filePath: string,
    fileBytes: Buffer | null,
    commitLogMessage: string,
    unixSeconds: number,
  ): { commit: string; blob: string | null } {
    const splitSegments = filePath.split('/').filter((seg) => seg.length > 0)
    let createdBlobSha: string | null = null
    if (fileBytes !== null) {
      createdBlobSha = this.objects.store('blob', fileBytes)
    }
    const currentTip = repository.branchSha(targetBranch)
    const rootTreeSha = currentTip ? this.commitTree(currentTip) : null
    const entrySpec = fileBytes === null ? null : { mode: '100644', sha: createdBlobSha! }
    const updatedTreeSha = updateTreePath(this.objects, rootTreeSha, splitSegments, entrySpec) ?? EMPTY_TREE
    const synthesizedCommit = makeCommit(this.objects, {
      tree: updatedTreeSha,
      parents: currentTip ? [currentTip] : [],
      message: commitLogMessage,
      tsSec: unixSeconds,
    })
    repository.setRef(`refs/heads/${targetBranch}`, synthesizedCommit)
    return { commit: synthesizedCommit, blob: createdBlobSha }
  }

  commitTree(commitOid: string): string {
    const commitObj = this.objects.get(commitOid)
    if (!commitObj) return EMPTY_TREE
    const match = commitObj.data.toString('utf8').match(/^tree ([0-9a-f]{40})/m)
    return match ? match[1] : EMPTY_TREE
  }

  fileAt(repository: Repo, branchName: string, targetPath: string): { mode: string; sha: string } | null {
    const headTip = repository.branchSha(branchName)
    if (!headTip) return null
    const rootTree = this.commitTree(headTip)
    const pathParts = targetPath.split('/').filter((p) => p.length > 0)
    let currentLevel: TreeEntry | null = { mode: '40000', name: '', sha: rootTree }
    for (let i = 0; i < pathParts.length; i++) {
      if (!currentLevel) return null
      const treeRec = this.objects.get(currentLevel.sha)
      if (!treeRec) return null
      const matchedEntry = parseTree(treeRec.data).find((e) => e.name === pathParts[i])
      if (!matchedEntry) return null
      if (i === pathParts.length - 1) return { mode: matchedEntry.mode, sha: matchedEntry.sha }
      if (!isDirMode(matchedEntry.mode)) return null
      currentLevel = matchedEntry
    }
    return currentLevel ? { mode: currentLevel.mode, sha: currentLevel.sha } : null
  }

  listDir(repository: Repo, branchName: string, folderPath: string): Array<{ mode: string; name: string; sha: string; kind: 'file' | 'dir' }> {
    const headTip = repository.branchSha(branchName)
    if (!headTip) return []
    const rootTree = this.commitTree(headTip)
    const folderSegments = folderPath.split('/').filter((s) => s.length > 0)
    let activeDirSha = rootTree
    for (const folderSeg of folderSegments) {
      const treeRec = this.objects.get(activeDirSha)
      if (!treeRec) return []
      const childDir = parseTree(treeRec.data).find((e) => e.name === folderSeg && isDirMode(e.mode))
      if (!childDir) return []
      activeDirSha = childDir.sha
    }
    const finalTree = this.objects.get(activeDirSha)
    if (!finalTree) return []
    return parseTree(finalTree.data).map((entry) => ({
      mode: entry.mode,
      name: entry.name,
      sha: entry.sha,
      kind: isDirMode(entry.mode) ? 'dir' : 'file',
    }))
  }

  // ---- merge helpers ----

  /** Squash-merge `pull`: tree from head, single parent = base tip, onto base branch. */
  squashMerge(repository: Repo, pullRequest: PullRec, mergeMsg: string, unixTimestamp: number): string {
    const headCommit = repository.branchSha(pullRequest.headRef)
    if (!headCommit) throw new Error('head branch missing')
    const headTreeSha = this.commitTree(headCommit)
    const baseCommit = repository.branchSha(pullRequest.baseRef) ?? ''
    const mergedSha = makeCommit(this.objects, {
      tree: headTreeSha,
      parents: [baseCommit],
      message: mergeMsg,
      tsSec: unixTimestamp,
    })
    repository.setRef(`refs/heads/${pullRequest.baseRef}`, mergedSha)
    return mergedSha
  }

  changedPathsBetween(
    sourceTreeSha: string | null,
    targetTreeSha: string | null,
  ): Map<string, { a: { mode: string; sha: string } | null; b: { mode: string; sha: string } | null }> {
    const pathMap = new Map<string, { a: { mode: string; sha: string } | null; b: { mode: string; sha: string } | null }>()
    const recordFileSide = (fPath: string, branchSide: 'a' | 'b', entryVal: { mode: string; sha: string } | null): void => {
      const existingRecord = pathMap.get(fPath) ?? { a: null, b: null }
      existingRecord[branchSide] = entryVal
      pathMap.set(fPath, existingRecord)
    }
    if (sourceTreeSha) {
      for (const [blobPath, blobData] of treeClosure(this.objects, sourceTreeSha).blobs) {
        recordFileSide(blobPath, 'a', blobData)
      }
    }
    if (targetTreeSha) {
      for (const [blobPath, blobData] of treeClosure(this.objects, targetTreeSha).blobs) {
        recordFileSide(blobPath, 'b', blobData)
      }
    }
    return pathMap
  }

  /** 3-way conflict check for a pull request. Returns true when conflicted. */
  isConflicted(repository: Repo, pullRequest: PullRec): boolean {
    const headCommitSha = repository.branchSha(pullRequest.headRef)
    const baseCommitSha = repository.branchSha(pullRequest.baseRef)
    if (!headCommitSha || !baseCommitSha) return false
    const baseAncestorSet = new Set<string>([baseCommitSha])
    const searchQueue = [baseCommitSha]
    while (searchQueue.length) {
      const currentOid = searchQueue.shift()!
      const rec = this.objects.get(currentOid)
      if (!rec) continue
      for (const line of rec.data.toString('utf8').split('\n')) {
        if (line.startsWith('parent ')) {
          const p = line.slice(7).trim()
          if (!baseAncestorSet.has(p)) {
            baseAncestorSet.add(p)
            searchQueue.push(p)
          }
        } else if (line === '') break
      }
    }
    let commonBaseOid: string | null = null
    const headVisited = new Set<string>([headCommitSha])
    const headQueue = [headCommitSha]
    while (headQueue.length) {
      const curHeadOid = headQueue.shift()!
      if (baseAncestorSet.has(curHeadOid)) {
        commonBaseOid = curHeadOid
        break
      }
      const rec = this.objects.get(curHeadOid)
      if (!rec) continue
      for (const line of rec.data.toString('utf8').split('\n')) {
        if (line.startsWith('parent ')) {
          const p = line.slice(7).trim()
          if (!headVisited.has(p)) {
            headVisited.add(p)
            headQueue.push(p)
          }
        } else if (line === '') break
      }
    }
    const baseTreeOid = this.commitTree(baseCommitSha)
    const headTreeOid = this.commitTree(headCommitSha)
    const commonTreeOid = commonBaseOid ? this.commitTree(commonBaseOid) : null
    const baseDiff = this.changedPathsBetween(commonTreeOid, baseTreeOid)
    const headDiff = this.changedPathsBetween(commonTreeOid, headTreeOid)
    for (const [diffPath, headBlob] of headDiff) {
      const baseBlob = baseDiff.get(diffPath)
      if (!baseBlob) continue
      const baseModified = (baseBlob.a?.sha ?? null) !== (baseBlob.b?.sha ?? null)
      const headModified = (headBlob.a?.sha ?? null) !== (headBlob.b?.sha ?? null)
      if (!baseModified || !headModified) continue
      const baseVersionSha = baseBlob.b?.sha ?? null
      const headVersionSha = headBlob.b?.sha ?? null
      if (baseVersionSha !== headVersionSha) return true
    }
    return false
  }
}

export function storeObject(targetStore: Store, objectKind: ObjType, binaryPayload: Buffer): string {
  return targetStore.objects.store(objectKind, binaryPayload)
}

export function emptyTreeSha(targetStore: Store): string {
  if (!targetStore.objects.has(EMPTY_TREE)) {
    targetStore.objects.store('tree', serializeTree([]))
  }
  return EMPTY_TREE
}

// HTTP dispatch plumbing: request body buffering, content negotiation, authentication gate, and API routing.
import http from 'node:http'
import zlib from 'node:zlib'
import { Store } from './store.ts'
import { handleRest } from './rest.ts'
import { handleGraphQL } from './graphql.ts'
import { handleMcp } from './mcp.ts'
import { handleGit } from './smarthttp.ts'

function readIncomingBody(inStream: http.IncomingMessage, byteCap = 512 * 1024 * 1024): Promise<Buffer> {
  return new Promise((fulfill, reject) => {
    const streamChunks: Buffer[] = []
    let totalBytesRead = 0
    inStream.on('data', (dataChunk: Buffer) => {
      totalBytesRead += dataChunk.length
      if (totalBytesRead > byteCap) {
        reject(new Error('Payload exceeds maximum allowed size'))
        inStream.destroy()
        return
      }
      streamChunks.push(dataChunk)
    })
    inStream.on('end', () => fulfill(Buffer.concat(streamChunks)))
    inStream.on('error', reject)
  })
}

export function createForgeServer(dataStore: Store): http.Server {
  const forgeApp = http.createServer((clientReq, clientRes) => {
    void processClientRequest(dataStore, clientReq, clientRes)
  })
  forgeApp.on('checkContinue', (clientReq, clientRes) => {
    clientRes.writeContinue()
    void processClientRequest(dataStore, clientReq, clientRes)
  })
  forgeApp.keepAliveTimeout = 65_000
  forgeApp.requestTimeout = 0
  forgeApp.headersTimeout = 60_000
  return forgeApp
}

async function processClientRequest(
  dataStore: Store,
  incomingReq: http.IncomingMessage,
  outgoingRes: http.ServerResponse,
): Promise<void> {
  try {
    const parsedUrl = new URL(incomingReq.url ?? '/', 'http://localhost')
    const requestPath = parsedUrl.pathname
    let bodyBuffer: Buffer | null = null
    if (incomingReq.method !== 'GET' && incomingReq.method !== 'HEAD') {
      bodyBuffer = await readIncomingBody(incomingReq)
      const contentEncodingHeader = String(incomingReq.headers['content-encoding'] ?? '').toLowerCase()
      if (contentEncodingHeader.includes('gzip') && bodyBuffer.length > 0) {
        try {
          bodyBuffer = zlib.gunzipSync(bodyBuffer)
        } catch {
          sendJsonResponse(outgoingRes, 400, { message: 'Problems parsing JSON' })
          return
        }
      }
    } else {
      bodyBuffer = Buffer.alloc(0)
    }

    // Health probe (env boot check: 200 {"ok":true})
    if (requestPath === '/healthz' && (incomingReq.method === 'GET' || incomingReq.method === 'HEAD')) {
      const healthPayload = Buffer.from(JSON.stringify({ ok: true }) + '\n', 'utf8')
      outgoingRes.writeHead(200, {
        'Content-Type': 'application/json; charset=utf-8',
        'Content-Length': String(healthPayload.length),
      })
      outgoingRes.end(healthPayload)
      return
    }

    // Model Context Protocol (MCP) stream endpoint
    if (requestPath === '/mcp') {
      const authHeaderStr = String(incomingReq.headers.authorization ?? '')
      const bearerTokenVal = authHeaderStr.startsWith('Bearer ') ? authHeaderStr.slice(7).trim() : null
      const expectedToken = process.env.MAKEFUN_SHOP_TOKEN
      const isAuthorized =
        bearerTokenVal !== null &&
        bearerTokenVal.length > 0 &&
        (expectedToken === undefined || expectedToken === '' || bearerTokenVal === expectedToken)
      if (!isAuthorized) {
        sendJsonResponse(outgoingRes, 401, { message: 'Requires authentication' })
        return
      }
      if (incomingReq.method !== 'POST') {
        sendJsonResponse(outgoingRes, 405, { message: 'method not allowed' })
        return
      }
      const activeSessionId =
        typeof incomingReq.headers['mcp-session-id'] === 'string'
          ? (incomingReq.headers['mcp-session-id'] as string)
          : null
      handleMcp(dataStore, bodyBuffer.toString('utf8'), outgoingRes, activeSessionId, (statusCode, replyBody, sid) => {
        const replyHeaders: Record<string, string> = { 'Content-Length': String(replyBody.length) }
        if (replyBody.length > 0) replyHeaders['Content-Type'] = 'application/json'
        if (sid) replyHeaders['Mcp-Session-Id'] = sid
        outgoingRes.writeHead(statusCode, replyHeaders)
        outgoingRes.end(replyBody)
      })
      return
    }

    // Git Smart HTTP transport routing: public access
    if (!requestPath.startsWith('/api/')) {
      const hasGitSuffix =
        requestPath.endsWith('.git/info/refs') ||
        requestPath.endsWith('.git/git-upload-pack') ||
        requestPath.endsWith('.git/git-receive-pack') ||
        requestPath.includes('.git/')
      if (hasGitSuffix || /^\/[^/]+\/[^/]+\.git(\/|$)/.test(requestPath)) {
        const gitHandled = handleGit(
          dataStore,
          incomingReq.method ?? 'GET',
          requestPath,
          parsedUrl.searchParams,
          incomingReq.headers,
          bodyBuffer,
          outgoingRes,
        )
        if (gitHandled) return
      }
      sendJsonResponse(outgoingRes, 404, { message: 'Not Found' })
      return
    }

    // Authentication verification for REST and GraphQL surfaces
    const authVal = String(incomingReq.headers.authorization ?? '')
    const tokenCandidate = authVal.startsWith('Bearer ') ? authVal.slice(7).trim() : null
    const targetToken = process.env.MAKEFUN_SHOP_TOKEN
    const hasValidToken =
      tokenCandidate !== null &&
      tokenCandidate.length > 0 &&
      (targetToken === undefined || targetToken === '' || tokenCandidate === targetToken)
    if (!hasValidToken) {
      sendJsonResponse(outgoingRes, 401, { message: 'Requires authentication' })
      return
    }

    if (requestPath === '/api/graphql') {
      if (incomingReq.method !== 'POST') {
        sendJsonResponse(outgoingRes, 404, { message: 'Not Found' })
        return
      }
      handleGraphQL(dataStore, bodyBuffer.toString('utf8'), extractBaseUrl(incomingReq), outgoingRes)
      return
    }

    if (requestPath.startsWith('/api/v3')) {
      const pathSegs = requestPath.slice('/api/v3'.length).split('/').filter((s) => s.length > 0)
      let parsedBodyJson: Record<string, unknown> | null = null
      if (
        incomingReq.method === 'POST' ||
        incomingReq.method === 'PUT' ||
        incomingReq.method === 'PATCH' ||
        incomingReq.method === 'DELETE'
      ) {
        const bodyRawText = bodyBuffer.toString('utf8').trim()
        if (bodyRawText.length > 0) {
          try {
            parsedBodyJson = JSON.parse(bodyRawText) as Record<string, unknown>
            if (parsedBodyJson === null || typeof parsedBodyJson !== 'object' || Array.isArray(parsedBodyJson)) {
              parsedBodyJson = parsedBodyJson as Record<string, unknown>
            }
          } catch {
            sendJsonResponse(outgoingRes, 400, { message: 'Problems parsing JSON' })
            return
          }
        }
      }
      const restHandled = handleRest(
        dataStore,
        incomingReq.method ?? 'GET',
        pathSegs,
        parsedUrl.searchParams,
        parsedBodyJson,
        extractBaseUrl(incomingReq),
        outgoingRes,
      )
      if (restHandled) return
      sendJsonResponse(outgoingRes, 404, { message: 'Not Found' })
      return
    }

    sendJsonResponse(outgoingRes, 404, { message: 'Not Found' })
  } catch (err) {
    try {
      sendJsonResponse(outgoingRes, 500, { message: `Internal Server Error: ${(err as Error).message}` })
    } catch {
      // Stream already committed
    }
  }
}

function extractBaseUrl(reqMsg: http.IncomingMessage): string {
  const hostVal = String(reqMsg.headers.host ?? 'localhost')
  return `http://${hostVal}`
}

function sendJsonResponse(resObj: http.ServerResponse, code: number, payloadObj: unknown): void {
  const binaryPayload = Buffer.from(JSON.stringify(payloadObj), 'utf8')
  resObj.writeHead(code, {
    'Content-Type': 'application/json; charset=utf-8',
    'X-GitHub-Request-Id': 'req-unknown',
    'Content-Length': String(binaryPayload.length),
  })
  resObj.end(binaryPayload)
}

// Git smart HTTP service engine: protocol v2 and v0 advertisements, upload-pack negotiation, pack streaming, and atomic receive-pack processing.
import type http from 'node:http'
import {
  pkt,
  FLUSH,
  DELIM,
  readPkts,
  packObjects,
  unpackPack,
  sidebandChunk,
  type ObjType,
} from './packfile.ts'
import { treeClosure, isAncestor, type ObjectStore } from './objects.ts'
import type { Store, Repo } from './store.ts'

const EMPTY_ZERO_OID = '0000000000000000000000000000000000000000'
const FORGE_AGENT_HEADER = 'agent=forge/1.0'

function writeGitResponse(
  clientRes: http.ServerResponse,
  statusCode: number,
  mimeType: string,
  responseContent: Buffer | string,
): void {
  const binaryPayload = Buffer.isBuffer(responseContent) ? responseContent : Buffer.from(responseContent, 'latin1')
  clientRes.writeHead(statusCode, {
    'Content-Type': mimeType,
    'Cache-Control': 'no-cache',
    'Content-Length': String(binaryPayload.length),
  })
  clientRes.end(binaryPayload)
}

const MIME_ADV_UPLOAD = 'application/x-git-upload-pack-advertisement'
const MIME_ADV_RECEIVE = 'application/x-git-receive-pack-advertisement'
const MIME_RESULT_UPLOAD = 'application/x-git-upload-pack-result'
const MIME_RESULT_RECEIVE = 'application/x-git-receive-pack-result'

function getSortedReferences(repository: Repo): Array<{ name: string; sha: string }> {
  const referenceList: Array<{ name: string; sha: string }> = []
  for (const refName of repository.refs.keys()) {
    referenceList.push({ name: refName, sha: repository.refs.get(refName)! })
  }
  referenceList.sort((left, right) => (left.name < right.name ? -1 : left.name > right.name ? 1 : 0))
  return referenceList
}

// ---- advertisements ----

function advertiseUploadProtocolV2(clientRes: http.ServerResponse): void {
  const payloadPkt = Buffer.concat([
    pkt('version 2\n'),
    pkt(FORGE_AGENT_HEADER + '\n'),
    pkt('ls-refs=unborn\n'),
    pkt('fetch=shallow\n'),
    FLUSH,
  ])
  writeGitResponse(clientRes, 200, MIME_ADV_UPLOAD, payloadPkt)
}

function buildReferenceAdvertisement(repository: Repo, capabilitiesStr: string, attachHeadRef: boolean): Buffer {
  const outputPackets: Buffer[] = []
  const sortedRefsList = getSortedReferences(repository)
  const defaultHeadSha = repository.branchSha(repository.defaultBranch)
  let initialCapsEmitted = false
  if (attachHeadRef && defaultHeadSha) {
    outputPackets.push(pkt(`${defaultHeadSha} HEAD\0${capabilitiesStr}\n`))
    initialCapsEmitted = true
  }
  let isFirstRef = true
  for (const refItem of sortedRefsList) {
    if (isFirstRef && !initialCapsEmitted) {
      outputPackets.push(pkt(`${refItem.sha} ${refItem.name}\0${capabilitiesStr}\n`))
      initialCapsEmitted = true
    } else {
      outputPackets.push(pkt(`${refItem.sha} ${refItem.name}\n`))
    }
    isFirstRef = false
  }
  if (!initialCapsEmitted) {
    outputPackets.push(pkt(`${EMPTY_ZERO_OID} capabilities^{}\0${capabilitiesStr}\n`))
  }
  outputPackets.push(FLUSH)
  return Buffer.concat(outputPackets)
}

function advertiseUploadProtocolV0(clientRes: http.ServerResponse, repository: Repo): void {
  const protocolCaps = `symref=HEAD:refs/heads/${repository.defaultBranch} multi_ack_detailed multi_ack side-band-64k thin-pack ofs-delta ${FORGE_AGENT_HEADER}`
  const bodyBuffer = Buffer.concat([
    pkt(`# service=git-upload-pack\n`),
    FLUSH,
    buildReferenceAdvertisement(repository, protocolCaps, true),
  ])
  writeGitResponse(clientRes, 200, MIME_ADV_UPLOAD, bodyBuffer)
}

function advertiseReceiveProtocolV0(clientRes: http.ServerResponse, repository: Repo): void {
  const protocolCaps = `report-status delete-refs side-band-64k ofs-delta quiet ${FORGE_AGENT_HEADER}`
  const bodyBuffer = Buffer.concat([
    pkt(`# service=git-receive-pack\n`),
    FLUSH,
    buildReferenceAdvertisement(repository, protocolCaps, false),
  ])
  writeGitResponse(clientRes, 200, MIME_ADV_RECEIVE, bodyBuffer)
}

// ---- v2 ls-refs ----

function peelAnnotatedTag(storage: ObjectStore, sourceSha: string): string | null {
  let inspectOid = sourceSha
  for (let step = 0; step < 10; step++) {
    const objRec = storage.get(inspectOid)
    if (!objRec || objRec.type !== 'tag') {
      return inspectOid !== sourceSha ? inspectOid : null
    }
    const targetMatch = objRec.data.toString('utf8').match(/^object ([0-9a-f]{40})/m)
    if (!targetMatch) return null
    inspectOid = targetMatch[1]
  }
  return null
}

function handleLsRefsCommand(dataStore: Store, repository: Repo, argumentsList: string[], clientRes: http.ServerResponse): void {
  const filterPrefixes: string[] = []
  let wantSymrefs = false
  let wantPeel = false
  let wantUnborn = false
  for (const item of argumentsList) {
    if (item.startsWith('ref-prefix ')) filterPrefixes.push(item.slice('ref-prefix '.length))
    else if (item === 'symrefs') wantSymrefs = true
    else if (item === 'peel') wantPeel = true
    else if (item === 'unborn') wantUnborn = true
  }
  const prefixPredicate = (candidateName: string): boolean => {
    if (filterPrefixes.length === 0) return true
    return filterPrefixes.some((pfx) => candidateName.startsWith(pfx))
  }
  const responseChunks: Buffer[] = []
  const defaultBranchSha = repository.branchSha(repository.defaultBranch)
  if (defaultBranchSha) {
    if (prefixPredicate('HEAD')) {
      const symrefSuffix = wantSymrefs ? ` symref-target:refs/heads/${repository.defaultBranch}` : ''
      responseChunks.push(pkt(`${defaultBranchSha} HEAD${symrefSuffix}\n`))
    }
  } else if (wantUnborn && prefixPredicate('HEAD')) {
    const symrefSuffix = wantSymrefs ? ` symref-target:refs/heads/${repository.defaultBranch}` : ''
    responseChunks.push(pkt(`unborn HEAD${symrefSuffix}\n`))
  }
  for (const refEntry of getSortedReferences(repository)) {
    if (!prefixPredicate(refEntry.name)) continue
    const peeledTarget = wantPeel ? peelAnnotatedTag(dataStore.objects, refEntry.sha) : null
    const peelAnnotation = peeledTarget ? ` peeled:${peeledTarget}` : ''
    responseChunks.push(pkt(`${refEntry.sha} ${refEntry.name}${peelAnnotation}\n`))
  }
  responseChunks.push(FLUSH)
  writeGitResponse(clientRes, 200, MIME_RESULT_UPLOAD, Buffer.concat(responseChunks))
}

// ---- pack assembly for fetch ----

function collectTransferObjects(
  dataStore: Store,
  repository: Repo,
  requestedTips: string[],
  excludedTips: string[],
  shallowLimitDepth: number,
): {
  objs: Array<{ type: ObjType; data: Buffer }>
  shallow: string[]
} {
  const storage = dataStore.objects
  const commitCollection: string[] = []
  const shallowCutoffs: string[] = []
  if (shallowLimitDepth > 0) {
    const commitDepths = new Map<string, number>()
    const traversalQueue: string[] = []
    for (const tip of requestedTips) {
      if (!commitDepths.has(tip) && storage.has(tip)) {
        commitDepths.set(tip, 1)
        traversalQueue.push(tip)
      }
    }
    while (traversalQueue.length) {
      const currentCommit = traversalQueue.shift()!
      const currentDepth = commitDepths.get(currentCommit)!
      if (currentDepth >= shallowLimitDepth) {
        shallowCutoffs.push(currentCommit)
        commitCollection.push(currentCommit)
        continue
      }
      commitCollection.push(currentCommit)
      const objRec = storage.get(currentCommit)
      if (!objRec) continue
      for (const line of objRec.data.toString('utf8').split('\n')) {
        if (line === '') break
        if (line.startsWith('parent ')) {
          const parentOid = line.slice(7).trim()
          if (!commitDepths.has(parentOid) && storage.has(parentOid)) {
            commitDepths.set(parentOid, currentDepth + 1)
            traversalQueue.push(parentOid)
          }
        }
      }
    }
  } else {
    for (const tip of requestedTips) {
      const visitedCommits = new Set<string>([tip])
      const bfsQueue = [tip]
      while (bfsQueue.length) {
        const curOid = bfsQueue.shift()!
        commitCollection.push(curOid)
        const objRec = storage.get(curOid)
        if (!objRec) continue
        for (const line of objRec.data.toString('utf8').split('\n')) {
          if (line === '') break
          if (line.startsWith('parent ')) {
            const parentOid = line.slice(7).trim()
            if (!visitedCommits.has(parentOid) && storage.has(parentOid)) {
              visitedCommits.add(parentOid)
              bfsQueue.push(parentOid)
            }
          }
        }
      }
    }
  }
  const excludedObjectSet = new Set<string>()
  if (shallowLimitDepth === 0) {
    for (const haveTip of excludedTips) {
      const ancSet = new Set<string>([haveTip])
      const ancQueue = [haveTip]
      while (ancQueue.length) {
        const curOid = ancQueue.shift()!
        excludedObjectSet.add(curOid)
        const objRec = storage.get(curOid)
        if (!objRec) continue
        for (const line of objRec.data.toString('utf8').split('\n')) {
          if (line === '') break
          if (line.startsWith('parent ')) {
            const parentOid = line.slice(7).trim()
            if (!ancSet.has(parentOid) && storage.has(parentOid)) {
              ancSet.add(parentOid)
              ancQueue.push(parentOid)
            }
          }
        }
        const commitTreeOid = dataStore.commitTree(curOid)
        if (storage.has(commitTreeOid)) {
          const treeData = treeClosure(storage, commitTreeOid)
          for (const subTreeSha of treeData.trees) excludedObjectSet.add(subTreeSha)
          for (const blobMeta of treeData.blobs.values()) excludedObjectSet.add(blobMeta.sha)
        }
      }
    }
  } else {
    for (const haveTip of excludedTips) {
      excludedObjectSet.add(haveTip)
    }
  }
  const includedSet = new Set<string>()
  const finalObjectPack: Array<{ type: ObjType; data: Buffer }> = []
  const appendObject = (targetSha: string): void => {
    if (includedSet.has(targetSha) || excludedObjectSet.has(targetSha)) return
    const rec = storage.get(targetSha)
    if (!rec) return
    includedSet.add(targetSha)
    finalObjectPack.push({ type: rec.type, data: rec.data })
  }
  for (const cSha of commitCollection) {
    appendObject(cSha)
    const commitTreeSha = dataStore.commitTree(cSha)
    const closureData = treeClosure(storage, commitTreeSha)
    for (const treeSha of closureData.trees) appendObject(treeSha)
    for (const blobInfo of closureData.blobs.values()) appendObject(blobInfo.sha)
  }
  return { objs: finalObjectPack, shallow: shallowCutoffs }
}

function handleV2FetchCommand(
  dataStore: Store,
  repository: Repo,
  commandArgs: string[],
  clientRes: http.ServerResponse,
): void {
  const wantsOids: string[] = []
  const havesOids: string[] = []
  let isDoneAcknowledged = false
  let requestedDeepen = 0
  let sidebandEnabled = false
  for (const argItem of commandArgs) {
    if (argItem.startsWith('want ')) wantsOids.push(argItem.slice(5).trim())
    else if (argItem.startsWith('have ')) havesOids.push(argItem.slice(5).trim())
    else if (argItem === 'done') isDoneAcknowledged = true
    else if (argItem.startsWith('deepen ')) requestedDeepen = parseInt(argItem.slice(7), 10)
    else if (argItem === 'sideband-64k') sidebandEnabled = true
    else if (
      argItem === 'thin-pack' ||
      argItem === 'no-progress' ||
      argItem === 'include-tag' ||
      argItem === 'ofs-delta' ||
      argItem.startsWith('filter ') ||
      argItem.startsWith('shallow ') ||
      argItem === 'deepen-relative' ||
      argItem.startsWith('deepen-not ') ||
      argItem === 'wait-for-done' ||
      argItem === 'sideband-all'
    ) {
      // Ignored non-affecting protocol v2 capability flags
    }
  }
  const existingWants = wantsOids.filter((wSha) => dataStore.objects.has(wSha))
  if (!isDoneAcknowledged) {
    const ackBody = Buffer.concat([pkt('acknowledgments\n'), pkt('nak\n'), FLUSH])
    writeGitResponse(clientRes, 200, MIME_RESULT_UPLOAD, ackBody)
    return
  }
  const { objs, shallow } = collectTransferObjects(
    dataStore,
    repository,
    existingWants,
    havesOids,
    requestedDeepen > 0 ? requestedDeepen : 0,
  )
  const responseParts: Buffer[] = []
  if (shallow.length > 0) {
    responseParts.push(pkt('shallow-info\n'))
    for (const cutSha of shallow) responseParts.push(pkt(`shallow ${cutSha}\n`))
    responseParts.push(DELIM)
  }
  responseParts.push(pkt('packfile\n'))
  const binaryPack = packObjects(objs)
  responseParts.push(sidebandChunk(1, binaryPack))
  writeGitResponse(clientRes, 200, MIME_RESULT_UPLOAD, Buffer.concat(responseParts))
}

// ---- v0 upload-pack ----

function handleV0UploadPack(dataStore: Store, repository: Repo, requestBuffer: Buffer, clientRes: http.ServerResponse): void {
  const parsedLines = readPkts(requestBuffer)
  const wantList: string[] = []
  const haveList: string[] = []
  let useSideband = false
  let receivedDone = false
  for (const pktLine of parsedLines) {
    if (pktLine.kind !== 'data' || !pktLine.data) continue
    const lineText = pktLine.data.toString('latin1').replace(/\n$/, '')
    if (lineText.startsWith('want ')) {
      const remainder = lineText.slice(5)
      const spaceIdx = remainder.indexOf(' ')
      const targetSha = spaceIdx === -1 ? remainder : remainder.slice(0, spaceIdx)
      const capsSuffix = spaceIdx === -1 ? '' : remainder.slice(spaceIdx + 1)
      if (capsSuffix.includes('side-band-64k')) useSideband = true
      wantList.push(targetSha)
    } else if (lineText.startsWith('have ')) {
      haveList.push(lineText.slice(5).trim())
    } else if (lineText === 'done') {
      receivedDone = true
    }
  }
  const outputBuffers: Buffer[] = []
  outputBuffers.push(pkt('nak\n'))
  const resolvedWants = wantList.filter((oid) => dataStore.objects.has(oid))
  const { objs } = collectTransferObjects(dataStore, repository, resolvedWants, haveList, 0)
  const assembledPack = packObjects(objs)
  if (useSideband) {
    outputBuffers.push(sidebandChunk(1, assembledPack))
  } else {
    outputBuffers.push(assembledPack)
  }
  writeGitResponse(clientRes, 200, MIME_RESULT_UPLOAD, Buffer.concat(outputBuffers))
  void receivedDone
}

// ---- receive-pack ----

interface IncomingPushCommand {
  old: string
  new: string
  ref: string
}

function handleReceivePack(dataStore: Store, repository: Repo, requestBuffer: Buffer, clientRes: http.ServerResponse): void {
  const pushCommands: IncomingPushCommand[] = []
  let clientCapabilities = ''
  let parsePos = 0
  let encounteredFlush = false
  while (parsePos + 4 <= requestBuffer.length) {
    const segmentLength = parseInt(requestBuffer.toString('latin1', parsePos, parsePos + 4), 16)
    if (Number.isNaN(segmentLength)) break
    if (segmentLength === 0) {
      parsePos += 4
      encounteredFlush = true
      break
    }
    if (segmentLength === 1) {
      parsePos += 4
      continue
    }
    if (segmentLength === 2) {
      parsePos += 4
      encounteredFlush = true
      break
    }
    if (segmentLength < 4) break
    if (parsePos + segmentLength > requestBuffer.length) break
    const packetContent = requestBuffer.toString('latin1', parsePos + 4, parsePos + segmentLength)
    parsePos += segmentLength
    const nulByteIdx = packetContent.indexOf('\0')
    const primaryStr = nulByteIdx === -1 ? packetContent : packetContent.slice(0, nulByteIdx)
    if (nulByteIdx !== -1 && clientCapabilities === '') {
      clientCapabilities = packetContent.slice(nulByteIdx + 1).replace(/\n$/, '')
    }
    const sanitizedCmd = primaryStr.replace(/\n$/, '')
    if (sanitizedCmd.startsWith('shallow ') || sanitizedCmd.startsWith('unshallow ')) continue
    const cmdMatch = sanitizedCmd.match(/^([0-9a-f]{40}) ([0-9a-f]{40}) (.+)$/)
    if (cmdMatch) {
      pushCommands.push({ old: cmdMatch[1], new: cmdMatch[2], ref: cmdMatch[3] })
    }
  }
  const packPayloadBuffer = encounteredFlush ? requestBuffer.subarray(parsePos) : null
  const expectsStatusReport = clientCapabilities.includes('report-status')
  const expectsSidebandStream = clientCapabilities.includes('side-band-64k')
  const statusReportLines: string[] = []
  let unpackSucceeded = true
  if (packPayloadBuffer && packPayloadBuffer.length >= 32) {
    try {
      unpackPack(packPayloadBuffer, {
        get: (sha) => dataStore.objects.get(sha),
        store: (type: ObjType, data: Buffer) => dataStore.objects.store(type, data),
      })
    } catch (unpackErr) {
      unpackSucceeded = false
      statusReportLines.push(`unpack ${(unpackErr as Error).message}\n`)
      for (const cmd of pushCommands) {
        statusReportLines.push(`ng ${cmd.ref} n/a (unpack error)\n`)
      }
    }
  }
  if (unpackSucceeded) {
    statusReportLines.push('unpack ok\n')
    for (const cmd of pushCommands) {
      const activeOid = repository.refs.get(cmd.ref) ?? EMPTY_ZERO_OID
      let commandOk = false
      if (cmd.new === EMPTY_ZERO_OID) {
        if (activeOid !== EMPTY_ZERO_OID && cmd.old === activeOid) {
          repository.deleteRef(cmd.ref)
          commandOk = true
        }
        if (!commandOk) statusReportLines.push(`ng ${cmd.ref} non-fast-forward\n`)
      } else if (activeOid === EMPTY_ZERO_OID) {
        if (!repository.refs.has(cmd.ref)) {
          repository.setRef(cmd.ref, cmd.new)
          commandOk = true
        }
        if (!commandOk) statusReportLines.push(`ng ${cmd.ref} non-fast-forward\n`)
      } else if (cmd.old !== activeOid) {
        statusReportLines.push(`ng ${cmd.ref} non-fast-forward\n`)
      } else if (cmd.new === cmd.old) {
        commandOk = true
      } else if (isAncestor(dataStore.objects, cmd.old, cmd.new)) {
        repository.setRef(cmd.ref, cmd.new)
        commandOk = true
      } else {
        statusReportLines.push(`ng ${cmd.ref} non-fast-forward\n`)
      }
      if (commandOk) statusReportLines.push(`ok ${cmd.ref}\n`)
    }
  }
  if (!expectsStatusReport) {
    writeGitResponse(clientRes, 200, MIME_RESULT_RECEIVE, FLUSH)
    return
  }
  const reportPayloadBuffer = Buffer.concat([...statusReportLines.map((line) => pkt(line)), FLUSH])
  const finalOutput = expectsSidebandStream ? sidebandChunk(1, reportPayloadBuffer) : reportPayloadBuffer
  writeGitResponse(clientRes, 200, MIME_RESULT_RECEIVE, finalOutput)
}

// ---- v2 command dispatch ----

function handleV2UploadPack(
  dataStore: Store,
  repository: Repo,
  requestBuffer: Buffer,
  clientRes: http.ServerResponse,
): void {
  const parsedPackets = readPkts(requestBuffer)
  let subCommandName = ''
  const parsedArguments: string[] = []
  let readingArguments = false
  for (const packetItem of parsedPackets) {
    if (packetItem.kind === 'delim') {
      readingArguments = true
      continue
    }
    if (packetItem.kind === 'flush') break
    if (packetItem.kind === 'data' && packetItem.data) {
      const packetStr = packetItem.data.toString('latin1').replace(/\n$/, '')
      if (!readingArguments && packetStr.startsWith('command=')) {
        subCommandName = packetStr.slice(8)
      } else if (readingArguments) {
        parsedArguments.push(packetStr)
      }
    }
  }
  if (subCommandName === 'ls-refs') {
    handleLsRefsCommand(dataStore, repository, parsedArguments, clientRes)
  } else if (subCommandName === 'fetch') {
    handleV2FetchCommand(dataStore, repository, parsedArguments, clientRes)
  } else {
    writeGitResponse(clientRes, 400, MIME_RESULT_UPLOAD, pkt(`err unknown command ${subCommandName}\n`) + FLUSH)
  }
}

// ---- entry ----

export function handleGit(
  dataStore: Store,
  httpVerb: string,
  urlPath: string,
  urlQueryParams: URLSearchParams,
  reqHeaders: http.IncomingHttpHeaders,
  requestBuffer: Buffer,
  clientRes: http.ServerResponse,
): boolean {
  const routeMatch = urlPath.match(/^\/([^/]+)\/([^/]+)\.git\/(info\/refs|git-upload-pack|git-receive-pack)$/)
  if (!routeMatch) return false
  const [, repoOwner, repoName, requestedAction] = routeMatch
  const protocolHeaderStr = String(reqHeaders['git-protocol'] ?? '')
  const isV2Protocol = protocolHeaderStr.includes('version=2')
  if (requestedAction === 'info/refs') {
    if (httpVerb !== 'GET') {
      writeGitResponse(clientRes, 405, 'application/json', JSON.stringify({ message: 'method not allowed' }))
      return true
    }
    const requestedService = urlQueryParams.get('service')
    const targetRepo = dataStore.getRepo(repoOwner, repoName)
    if (!targetRepo) {
      writeGitResponse(clientRes, 404, 'application/json', JSON.stringify({ message: 'Not Found' }))
      return true
    }
    if (requestedService === 'git-upload-pack') {
      if (isV2Protocol) advertiseUploadProtocolV2(clientRes)
      else advertiseUploadProtocolV0(clientRes, targetRepo)
    } else if (requestedService === 'git-receive-pack') {
      advertiseReceiveProtocolV0(clientRes, targetRepo)
    } else {
      writeGitResponse(clientRes, 400, 'application/json', JSON.stringify({ message: 'dumb http protocol not supported' }))
    }
    return true
  }
  const targetRepo = dataStore.getRepo(repoOwner, repoName)
  if (!targetRepo) {
    writeGitResponse(clientRes, 404, 'application/json', JSON.stringify({ message: 'Not Found' }))
    return true
  }
  if (requestedAction === 'git-upload-pack') {
    if (httpVerb !== 'POST') {
      writeGitResponse(clientRes, 405, 'application/json', JSON.stringify({ message: 'method not allowed' }))
      return true
    }
    const leadBytesLen = parseInt(requestBuffer.toString('latin1', 0, 4), 16)
    const initialLine = leadBytesLen > 4 ? requestBuffer.toString('latin1', 4, Math.min(leadBytesLen, requestBuffer.length)) : ''
    if (initialLine.startsWith('command=')) {
      handleV2UploadPack(dataStore, targetRepo, requestBuffer, clientRes)
    } else {
      handleV0UploadPack(dataStore, targetRepo, requestBuffer, clientRes)
    }
    return true
  }
  if (requestedAction === 'git-receive-pack') {
    if (httpVerb !== 'POST') {
      writeGitResponse(clientRes, 405, 'application/json', JSON.stringify({ message: 'method not allowed' }))
      return true
    }
    handleReceivePack(dataStore, targetRepo, requestBuffer, clientRes)
    return true
  }
  return false
}

